(* LPS 75d69e00: [ref_stdio_write] carries [m_channel_reader model = true], so this
   flush path (one registered atexit handler, axh = 0x12ec60) carries it too, after the
   fd_lookup premise. The recorded replay applied [@ref_stdio_write] at the old arity;
   it is replaced by this explicit proof, adapted from boost-beast http_request
   RefExit.v ref_exit_flush's atexit-one branch with boost-json's w1H/w2/w3b1/w3b2. *)
Theorem ref_exit_flushH :
  forall regs mem model (sp tp code : word) (tid : Z) (wp2 rp2 : word)
         (wb wp : Z) (bufp bufsz rp1 can : word) (pending : list byte),
  exit_common regs mem sp tp code tid wp2 rp2 0x12ec60 ->
  rdn RSEGS mem (Z_to_bv 64 0x12ec50) 4 = Some (word_to_le_bytes 4 (Z_to_bv 64 1)) ->
  rdn RSEGS mem (Z_to_bv 64 0x12ec60) 8 = Some (word_to_le_bytes 8 (Z_to_bv 64 0)) ->
  rdn RSEGS mem (Z_to_bv 64 0x12ec68) 8 = Some (word_to_le_bytes 8 (Z_to_bv 64 0xddc10)) ->
  rdn RSEGS mem (Z_to_bv 64 0x12ed68) 8 = Some (word_to_le_bytes 8 (Z_to_bv 64 0x4740c)) ->
  rdn RSEGS mem (Z_to_bv 64 0x10d144) 1 = Some [Z_to_bv 8 0] ->
  stdout_pending mem wb wp bufp bufsz rp1 can pending ->
  m_halted model = None -> m_vm_lazy model = [] ->
  fd_lookup (m_fds model) (Z_to_bv 64 1) = Some (FdChannel (Z_to_bv 64 1)) ->
  m_channel_reader model = true ->
  realizes RSEGS (mkCfg (mkst regs (0xddc64 : word) mem (seg_rom RSEGS)) model)
           (t_emit (W 1 pending) (t_exit (bv_and code (Z_to_bv 64 255)) (m_fs model))).
Proof.
  intros regs mem model sp tp code tid wp2 rp2 wb wp bufp bufsz rp1 can pending EC Mcnt Mf0 Mfn Marg Mincb SP Hh Hlazy Hfd Hrdr.
  destruct EC.
  destruct SP as [P1l P1wp P1wb P1wr P1buf P1bsz P1fd P1rp P1re RANGE LEN PMAX BYTES [Ggot Gcan]].
  zaddr P1l; zaddr P1wp; zaddr P1wb; zaddr P1wr; zaddr P1buf; zaddr P1bsz; zaddr P1fd; zaddr P1rp; zaddr P1re.
  destruct ec_glob as (Gnl & Gofl & Gin & Gout & Gerr).
  destruct (w1H regs mem (seg_rom RSEGS) sp tp code tid) as (regs1 & RUN1 & R1sp & R1s0 & R1ra & R1tp & R1gp & R1s1);
    try assumption.
  eapply rz_msteps; [exact Hh | exact Hlazy | exact RUN1 |]. clear RUN1.
  destruct (w2 regs1 (mem_w1H mem sp (getr regs 1) (getr regs 8) code (getr regs 9) (getr regs 18) (getr regs 19) tid) (seg_rom RSEGS) sp code (getr regs1 9))
    as (regs2 & RUN2 & R2sp & R2s0 & R2ra & R2s1 & R2tp & R2gp); try assumption; try reflexivity.
  all: try (unfold mem_w1H; first [store_ok_peel; exact ec_sok | rdn_solve]).
  eapply rz_msteps; [exact Hh | exact Hlazy | exact RUN2 |]. clear RUN2.
  destruct (w3b1 regs2 (mem_w2 (mem_w1H mem sp (getr regs 1) (getr regs 8) code (getr regs 9) (getr regs 18) (getr regs 19) tid) sp code (getr regs1 9))
              (seg_rom RSEGS) sp code wb wp)
    as (regs3 & RUN3 & R3a0 & R3a1 & R3a2 & R3ra & R3sp & R3s0 & R3gp & R3tp); try assumption; try lia.
  1:{ unfold mem_w2, mem_w1H; store_ok_peel; exact ec_sok. }
  1:{ repeat split; [zaddr Gnl|zaddr Gofl|zaddr Gin|zaddr Gout|zaddr Gerr]; unfold mem_w2, mem_w1H; rdn_solve. }
  1:{ repeat split; unfold mem_w2, mem_w1H; zaddr_goal; rdn_solve. }
  eapply rz_msteps; [exact Hh | exact Hlazy | exact RUN3 |]. clear RUN3.
  replace (Z_to_bv 64 0xe3438) with (0xe3438 : word) in R3ra by (apply bv_eq; reflexivity).
  unfold W. rewrite <- (app_nil_r pending).
  set (mem3 := mem_w3a (mem_w2 (mem_w1H mem sp (getr regs 1) (getr regs 8) code (getr regs 9) (getr regs 18) (getr regs 19) tid) sp code (getr regs1 9)) sp code).
  eapply (ref_stdio_write regs3 mem3 model (bv_unsigned sp - 32) 0xfcfd8 wb wp 1
            (Z_to_bv 64 0) (Z_to_bv 64 0) bufp bufsz can (0xe3438 : word) pending []);
    [ exact R3sp | exact R3a0 | exact R3a1 | exact R3a2 | exact R3ra
    | lia | lia
    | subst mem3; unfold mem_w3a, mem_w2, mem_w1H; sok_stack ec_sok
    | lia | lia
    | split; subst mem3; unfold mem_w3a, mem_w2, mem_w1H; zaddr_goal; rdn_solve
    | split; subst mem3; unfold mem_w3a, mem_w2, mem_w1H; rdn_solve
    | lia | exact Hfd | exact Hrdr | exact Hh | exact Hlazy
    | lia | lia | exact LEN
    | cbn [length]; u_norm; reflexivity
    | cbn [length]; lia
    | lia | u_norm; lia | u_norm; lia
    | subst mem3; unfold mem_w3a, mem_w2, mem_w1H; repeat rdn_peel1; exact BYTES
    | reflexivity
    | apply ret_ok_even; reflexivity
    | apply t_emit_has_nil
    | ].
  intros regs4 mem4 Q10 Q2 Q1 Q8 Q9 Q18 Q19 Q20 Q21 Q22 Q23 Q24 Q25 Q26 Q27 Q3 Q4 POST.
  rewrite R3s0 in Q8.
  destruct ec_err as (F2l & F2wp & F2wb & F2rp & F2re).
  zaddr F2l; zaddr F2wp; zaddr F2wb; zaddr F2rp; zaddr F2re.
  destruct (w3b2 regs4 mem4 (seg_rom RSEGS) sp code rp1 wp2 rp2) as (regs5 & RUN5 & R5a0 & R5a7 & R5sp); try assumption.
  all: try (eapply (sw_post_rdn _ _ _ _ _ _ _ _ _ POST); [subst mem3; unfold mem_w3a, mem_w2, mem_w1H; zaddr_goal; rdn_solve | zsimp; lia | zsimp; lia | zsimp; lia | zsimp; lia]).
  1:{ repeat split; (eapply (sw_post_rdn _ _ _ _ _ _ _ _ _ POST); [subst mem3; unfold mem_w3a, mem_w2, mem_w1H; zaddr_goal; rdn_solve | zsimp; lia | zsimp; lia | zsimp; lia | zsimp; lia]). }
  eapply rz_msteps; [exact Hh | exact Hlazy | exact RUN5 |]. clear RUN5.
  eapply rz_exit_at; [exact F_dd974 | exact E_dd974 | exact Hh | exact Hlazy | left; exact R5a7 | exact R5a0].
Qed.

(* [comment removed for export] *)
Lemma t_emit_nil_exitH : forall code fs, t_eq (t_exit code fs) (t_emit [] (t_exit code fs)).
Proof.
  intros code fs. apply t_eq_sym. apply t_emit_nil_eq.
  unfold t_exit, t_emit. left. apply is_prefix_nil.
Qed.

(* LPS 75d69e00: the flush arm needs the launch's channel reader; [exit_preH] is left
   as it was and the reader is a separate premise (as RefExit.ref_exit). *)
Theorem ref_exitH : forall regs mem model code pending,
  exit_preH regs mem model code pending ->
  m_channel_reader model = true ->
  realizes RSEGS (mkCfg (mkst regs (0xddc64 : word) mem (seg_rom RSEGS)) model)
           (t_emit (W 1 pending) (t_exit (bv_and code (Z_to_bv 64 255)) (m_fs model))).
Proof.
  intros regs mem model code pending (sp & tp & tid & wp2 & rp2 & EC & AX & Hh & Hlazy & CASES) Hrdr.
  destruct AX as (A1 & A2 & A3 & A4 & A5).
  destruct CASES as [(-> & wp1 & rp1 & F1) | (wb & wp & bufp & bufsz & rp1 & can & SP & Hfd)].
  - eapply rz_conseq; [ | apply t_emit_nil_exitH ].
    eapply ref_exit_cleanH; eassumption.
  - eapply ref_exit_flushH; eassumption.
Qed.

(* [comment removed for export] *)
Corollary ref_exitH_Z : forall regs mem model code pending,
  exit_preH regs mem model code pending ->
  m_channel_reader model = true ->
  realizes RSEGS (mkCfg (mkst regs (Z_to_bv 64 0xddc64) mem (seg_rom RSEGS)) model)
           (t_emit (W 1 pending) (t_exit (bv_and code (Z_to_bv 64 255)) (m_fs model))).
Proof.
  intros. replace (Z_to_bv 64 0xddc64) with (0xddc64 : word) by (apply bv_eq; reflexivity).
  apply ref_exitH; assumption.
Qed.
